/** Ask the person for a permission. Resolves when they answer. */
export interface PermRequestRequest {
  id: RequestId;
  method: "perm.request";
  params: PermRequestParams;
}

/** Parameters of perm.request. */
export interface PermRequestParams {
  permission: Permission;
  /** Why the caller asks, shown to the person in the prompt. Optional; a prompt without one says that none was given. */
  reason?: string;
  duration?: GrantDuration;
}

/** How long a grant lasts. once: the next call it allows, then it expires. session: until Desk quits. always: kept on disk across restarts. Every grant lasts until revoked at the latest. perm.request defaults to session. */
export type GrantDuration = "once" | "session" | "always";

/** Result of perm.request. A refusal is a result, not an error. A request that a lasting grant (session or always) already covers is granted at once with that grant, unless the caller is an agent and the grant lies outside its allowlist. */
export interface PermRequestResult {
  granted: boolean;
  grant?: Grant;
  reason?: RefusalReason;
}

/** Why perm.request was refused without asking the person. refused-earlier: the person refused this caller this permission and scope earlier in the session; it holds until the caller is granted a permission that covers it. outside-allowlist: the caller is an agent (agent:<id>) and no permission in agents.<id>.allow of init.yaml covers the request; an agent is never granted anything outside a non-empty allowlist (ADR 0072). Absent from a result means the person (or the core's own prompter) refused this request. */
export type RefusalReason = "refused-earlier" | "outside-allowlist";

/** List the caller's current grants. */
export interface PermQueryRequest {
  id: RequestId;
  method: "perm.query";
  params: PermQueryParams;
}

/** Parameters of perm.query. With permission, only grants that cover it are returned. */
export interface PermQueryParams {
  permission?: Permission;
}

/** Result of perm.query. */
export interface PermQueryResult {
  grants: Grant[];
}

/** Give a grant back. The person can also revoke any grant at any time. */
export interface PermRevokeRequest {
  id: RequestId;
  method: "perm.revoke";
  params: PermRevokeParams;
}

/** Parameters of perm.revoke. Without scope only the caller's own grants; with perm:manage any caller's. */
export interface PermRevokeParams {
  grantId: string;
  scope?: PermManagePermission;
}

/** Result of perm.revoke. */
export type PermRevokeResult = Record<string, never>;

/** A permission the person granted to the caller. */
export interface Grant {
  grantId: string;
  permission: Permission;
  duration: GrantDuration;
  /** RFC 3339 timestamp. */
  grantedAt: string;
  /** RFC 3339 timestamp; absent means for as long as the duration allows. */
  expiresAt?: string;
}

/** List every caller's grants, for the person's permissions view. */
export interface PermListRequest {
  id: RequestId;
  method: "perm.list";
  params: PermListParams;
}

/** Parameters of perm.list. With caller, only that caller's grants are returned. */
export interface PermListParams {
  caller?: CallerId;
  scope: PermManagePermission;
}

/** Result of perm.list, oldest grant first. */
export interface PermListResult {
  grants: CallerGrant[];
}

/** A grant together with the caller that holds it. */
export interface CallerGrant {
  caller: CallerId;
  grant: Grant;
}

/** The prompter answers a perm.prompt with the person's decision. */
export interface PermAnswerRequest {
  id: RequestId;
  method: "perm.answer";
  params: PermAnswerParams;
}

/** Parameters of perm.answer. duration is what the person chose; absent keeps the one asked for. */
export interface PermAnswerParams {
  promptId: string;
  granted: boolean;
  duration?: GrantDuration;
  /** true grants the prompt's parent offer instead of the permission asked. Ignored when granted is false; invalid_params on a prompt that offers no parent. */
  parent?: boolean;
  scope: PermManagePermission;
}

/** Result of perm.answer. */
export type PermAnswerResult = Record<string, never>;

/** A caller asked for a permission and the person has to decide. Sent to callers that hold perm:manage. An agent's caller is agent:<id>; it asks only within its allowlist. */
export interface PermPromptEvent {
  event: "perm.prompt";
  data: PermPromptData;
}

/** Payload of perm.prompt: who asks, for what, why and for how long. */
export interface PermPromptData {
  promptId: string;
  caller: CallerId;
  permission: Permission;
  /** The caller's reason, to show as it is. Absent when the caller gave none. */
  reason?: string;
  duration: GrantDuration;
  /** The parent folder the person may grant instead: the same permission over the folder that holds the one asked for, offered when this caller asks for a third folder under it in the session. Never a root, the home folder or a folder holding it, nor a scope the person refused this caller earlier, nor, for an agent, a scope outside its allowlist. */
  parent?: Permission;
}

/** An agent's irreversible call waits for the person's approval, even when a grant covers it (ADR 0078): an fs.write or a net.fetch whose target no always grant of the agent allows, a proc.spawn, or a cmd.invoke of a command its provider's manifest marks irreversible. Sent to callers that hold perm:manage; the first perm.approve decides. A caller that is not an agent is never held. */
export interface PermApprovalEvent {
  event: "perm.approval";
  data: PermApprovalData;
}

/** Payload of perm.approval: which agent, what it is about to do, to what, and what it would change. */
export interface PermApprovalData {
  approvalId: string;
  caller: CallerId;
  action: ApprovalAction;
  /** The scope the call carries, which a grant of the agent's covers. */
  permission: Permission;
  /** What the call touches: the path for fs.write, the command for proc.spawn, the URL for net.fetch, the command id for cmd.invoke, the fact for memory.remember. */
  target: string;
  preview?: ApprovalPreview;
  /** fs.write: the bytes it would write. */
  size?: number;
  /** The task the call belongs to: the desk's brain turn (brain.turn's turnId) whose tool call it is. Present only when there is one; only then may perm.approve answer task. */
  task?: string;
}

/** The bridge method an agent's irreversible call is. memory.remember is an agent keeping a fact in the person's memory: its target is the fact (ADR 0096). */
export type ApprovalAction =
  | "fs.write"
  | "proc.spawn"
  | "net.fetch"
  | "cmd.invoke"
  | "memory.remember";

/** What the call would do, as text. diff: a unified diff of the file as it is against what the write puts there (a new file is all additions), when both are UTF-8 text and the file is at most 1 MiB; the first 200 changed lines. command: the command line, quoted for a POSIX shell. url: the method and the URL. args: the command's args as JSON. fact: the fact memory.remember would keep. truncated says that the text was cut. */
export interface ApprovalPreview {
  kind: ApprovalPreviewKind;
  text: string;
  truncated?: boolean;
}

/** What a preview's text is: a unified diff, a command line, a method and URL, a command's args as JSON, or a fact to remember in the person's words. */
export type ApprovalPreviewKind = "diff" | "command" | "url" | "args" | "fact";

/** The prompter answers a perm.approval with the person's decision. */
export interface PermApproveRequest {
  id: RequestId;
  method: "perm.approve";
  params: PermApproveParams;
}

/** Parameters of perm.approve. */
export interface PermApproveParams {
  approvalId: string;
  answer: ApprovalAnswer;
  scope: PermManagePermission;
}

/** once: this call runs. task: this call runs, and so do the agent's later calls of the same action whose target the approved scope covers, until the task ends (invalid_params on an approval without a task). deny: this call is refused with permission_denied; the next one asks again. */
export type ApprovalAnswer = "once" | "task" | "deny";

/** Result of perm.approve. */
export type PermApproveResult = Record<string, never>;

/** An approved call ran: what came of it. Sent to callers that hold perm:manage. */
export interface PermApprovalDoneEvent {
  event: "perm.approval.done";
  data: PermApprovalDoneData;
}

/** Payload of perm.approval.done. */
export interface PermApprovalDoneData {
  approvalId: string;
  ok: boolean;
  /** fs.write: the bytes it wrote. */
  bytesWritten?: number;
  error?: BridgeError;
  /** true when cmd.undo can take the write back (#276). Absent while the core does not serve cmd.undo. */
  undoable?: boolean;
}

/** One of the caller's grants changed. */
export interface PermChangedEvent {
  event: "perm.changed";
  data: PermChangedData;
}

/** Payload of perm.changed. */
export interface PermChangedData {
  grantId: string;
  change: GrantChange;
}

/** What happened to the grant. */
export type GrantChange = "granted" | "revoked" | "expired";

